import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining polynomial, sinusoidal, and reciprocal components to create a non-trivial landscape.

    The function aims to balance exploration and exploitation by combining a global trend (polynomial),
    local optima (sinusoidal), and steep cliffs/barriers (reciprocal).

    Formula:
    f(x) = poly(x) + sin_prod(x) + recip_sum(x)

    Where:
        - poly(x) = sum((x_i)^4 - 2*(x_i)^2 + x_i) creates a polynomial trend
        - sin_prod(x) = prod(sin(2*pi*x_i)) introduces local optima
        - recip_sum(x) = sum(1 / (1 + (x_i - 0.5)^2)) adds sharp features.
    """

    def poly(x):
        return np.sum(x**4 - 2*x**2 + x)

    def sin_prod(x):
        return np.prod(np.sin(2 * np.pi * x))

    def recip_sum(x):
        return np.sum(1 / (1 + (x - 0.5)**2))

    return poly(x) + 0.1 * sin_prod(x) + 0.05*recip_sum(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a distance function, a cosine wave, a ridge, and a polynomial bias.

    Formula:
    f(x) = distance(x) + cos_wave(x) + ridge(x) + poly_bias(x)

    Where:
        - distance(x) = sqrt(sum(x_i^2))
        - cos_wave(x) = cos(w * distance(x)), where w is a random frequency.
        - ridge(x) = k * max(0, 1 - x_1), where k is a slope parameter.
        - poly_bias(x) = sum(0.1 * x_i^3 - 0.2 * x_i)
    """
    if x.shape[0] != 3:
        raise ValueError("Function is only defined for 3 dimensions.")

    def distance(x):
        return np.sqrt(np.sum(x**2))

    def cos_wave(x):
        w = 1.2  # Frequency of the cosine wave
        return np.cos(w * distance(x))

    def ridge(x):
        k = 0.5  # Slope of the ridge
        return k * np.maximum(0, 1 - x[0])

    def poly_bias(x):
        return np.sum(0.1 * x**3 - 0.2 * x)

    return distance(x) * 0.5 + cos_wave(x) * 0.2  + ridge(x) + poly_bias(x) * 0.1

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function combining a "mickey" component, a weighted sum, scaled cosine function and a non-separability introduction module.

    Formula:
    f(x) = mickey(x) + weighted_sum(x) + scaled_cos(x) + non_sep(x)

    Where:
      mickey(x) = sum(x_i^4)
      weighted_sum(x) = sum(i * x_i)
      scaled_cos(x) = sum(cos(x_i * pi))
      non_sep(x) = prod(x_i + x_j) where i != j
    """

    n = len(x)

    def mickey(x):
        return np.sum(x**4)

    def weighted_sum(x):
         return np.sum(np.arange(1, n + 1) * x)

    def scaled_cos(x):
        return np.sum(np.cos(x * np.pi))

    def non_sep(x):
        result = 1.0
        for i in range(n):
            for j in range(i+1, n):
              result *= (x[i] + x[j])
        return result

    return 0.01*mickey(x) + 0.005*weighted_sum(x) + 0.005*scaled_cos(x) + 0.0001*non_sep(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rastrigin-like term with a polynomial component to introduce skewness.

    This function attempts to improve the skewness and the fitness_std compared to the prior attempt while maintaining some modality provided by the Rastrigin function.

    Formula:
    f(x) = rastrigin_mod(x) + poly_term(x)

    Where:
        - rastrigin_mod(x) = 10*3 + sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])
        - poly_term(x) =  0.1 * (x[0]**3 + x[1]**2 - x[2])

    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rastrigin_mod(x):
        return 10*3 + sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])

    def poly_term(x):
        return 0.1 * (x[0]**3 + x[1]**2 - x[2])

    return rastrigin_mod(x) + poly_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a scaled-down Rastrigin-like term with a modified polynomial component to introduce skewness and fitness-distance correlation.

    This function attempts to match the target ELA features provided, focusing on skewness and fitness standard deviation adjustment.

    Formula:
    f(x) = 0.1 * rastrigin_mod(x) + 0.05 * poly_term(x)

    Where:
        - rastrigin_mod(x) = 10*3 + sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])
        - poly_term(x) =  (x[0]**3 + x[1]**2 - x[2]) + 2*x[0]*x[1] + 0.5*x[1]*x[2]

    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rastrigin_mod(x):
        return 10*3 + sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])

    def poly_term(x):
        return (x[0]**3 + x[1]**2 - x[2]) + 2*x[0]*x[1] + 0.5*x[1]*x[2]

    return 0.1 * rastrigin_mod(x) + 0.05 * poly_term(x)

