import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a dampened Rastrigin-like term with a polynomial component to introduce skewness.

    This function attempts to approximate targeted ELA features by reducing the Rastrigin amplitude and optimizing polynomial.

    Formula:
    f(x) = rastrigin_mod(x) + poly_term(x)

    Where:
        - rastrigin_mod(x) = sum([(xi**2 - 0.5 * np.cos(np.pi * xi)) for xi in x])
        - poly_term(x) =  0.1 * (x[0]**3 + 0.5*x[1]**2 - x[2] + x[0]*x[1])

    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rastrigin_mod(x):
        return sum([(xi**2 - 0.5 * np.cos(np.pi * xi)) for xi in x])

    def poly_term(x):
        return 0.1 * (x[0]**3 + 0.5*x[1]**2 - x[2] + x[0]*x[1])

    return rastrigin_mod(x) + poly_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rastrigin-like term with a polynomial component to introduce skewness and non-linearity.

    This function attempts to improve the skewness and the fitness_std compared to the prior attempt while maintaining some modality provided by the Rastrigin function.
    The polynomial term has been significantly altered to produce desired ELA values.

    Formula:
    f(x) = rastrigin_mod(x) + poly_term(x)

    Where:
        - rastrigin_mod(x) = 5*3 + 0.5 * sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])
        - poly_term(x) =  0.05 * (x[0]**3 + x[1]**2 - x[2])  / (1 + x[0]**2 + x[1]**2 + x[2]**2)
    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rastrigin_mod(x):
        return 5*3 + 0.5 * sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])

    def poly_term(x):
        return 0.05 * (x[0]**3 + x[1]**2 - x[2])  / (1 + x[0]**2 + x[1]**2 + x[2]**2)

    return rastrigin_mod(x) + poly_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a sum of exponentials with polynomial components and a global "valley".

    f(x) = sum(a_i * exp(-((x - c_i) @ B_i @ (x - c_i).T))) + poly_term(x) - valley(x)

    where:
        - a_i are positive weights
        - c_i are center vectors in R^3
        - B_i are positive definite matrices defining the shape of the exponentials
        - poly_term(x) adds a polynomial term for skewness and non-linearity: 0.1 * (x[0]**3 - x[1]**2 + x[2])
        - valley(x) creates a global valley: 0.5 * exp(-0.1 * (x[0]**2 + x[1]**2 + x[2]**2))
    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    a = np.array([1.0, 0.8, 0.6])
    c = np.array([[1.0, -0.5, 0.3], [-0.5, 1.0, -0.2], [0.0, -1.0, 1.0]])
    B = np.array([
        [[0.8, 0.1, 0.0], [0.1, 0.7, 0.0], [0.0, 0.0, 0.6]],
        [[0.6, -0.1, 0.0], [-0.1, 0.5, 0.0], [0.0, 0.0, 0.4]],
        [[0.5, 0.0, 0.1], [0.0, 0.4, -0.1], [0.1, -0.1, 0.3]]
    ])

    exponential_sum = 0.0
    for i in range(3):
        exponential_sum += a[i] * np.exp(-((x - c[i]) @ B[i] @ (x - c[i]).T))

    def poly_term(x):
        return 0.05 * (x[0]**3 - x[1]**2 + x[2])

    def valley(x):
        return 0.5 * np.exp(-0.1 * (x[0]**2 + x[1]**2 + x[2]**2))

    return exponential_sum + poly_term(x) - valley(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rosenbrock-like term with a rational polynomial to introduce skewness.

    Formula:
    f(x) = rosenbrock_mod(x) + rational_term(x)

    Where:
        - rosenbrock_mod(x) = sum([100.0 * (x[i+1] - x[i]**2)**2 + (1 - x[i])**2 for i in range(len(x)-1)])
        - rational_term(x) =  0.1 * (x[0]**3 + x[1]**2 - x[2])  / (1 + x[0]**2 + x[1]**2 + x[2]**2)
    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rosenbrock_mod(x):
        return sum([100.0 * (x[i+1] - x[i]**2)**2 + (1 - x[i])**2 for i in range(len(x)-1)]) if len(x) > 1 else 0

    def rational_term(x):
        return 0.1 * (x[0]**3 + x[1]**2 - x[2])  / (1 + x[0]**2 + x[1]**2 + x[2]**2)

    return rosenbrock_mod(x) + rational_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining sinusoidal waves, a polynomial term, and a modified Rosenbrock-like component.

    f(x) = sin_term(x) + poly_term(x) + rosenbrock_mod(x)

    Where:
        - sin_term(x) = a * sum(sin(b * x_i) for x_i in x)
        - poly_term(x) = c *(x[0]**3 + x[1]**2 - x[2])
        - rosenbrock_mod(x) = sum( [ (1-x[i])**2 + h*(x[i+1] - x[i]**2)**2  for i in range(len(x)-1)] )

    Goal: Control ELA features through these components. Specifically:
        * sinusoidal components -> modality & ruggedness
        * Polynomial term -> skewness
        * Rosenbrock component -> non-separability and variable correlation
    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    a = 2.0
    b = 1.5
    c = 0.1
    h = 50.0

    def sin_term(x):
        return a * np.sum(np.sin(b * x))

    def poly_term(x):
        return c * (x[0]**3 + x[1]**2 - x[2])

    def rosenbrock_mod(x):
        return np.sum([(1-x[i])**2 + h*(x[i+1] - x[i]**2)**2 for i in range(len(x)-1)])


    return sin_term(x) + poly_term(x) + rosenbrock_mod(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rosenbrock function, a rational skewing term, and a linear interaction term.

    f(x) = modified_rosenbrock(x) + skew_term(x) + linear_interaction(x)

    Where:
        - modified_rosenbrock(x) = sum(100.0 * (x[i+1] - x[i]**2)**2 + (1 - x[i])**2) for i in range(n-1), scaled and shifted to map typical output to a smaller range.
        - skew_term(x) = 0.1 * (x[0]**3 + x[1]**2 - x[2])  / (1 + x[0]**2 + x[1]**2 + x[2]**2).
        - linear_interaction(x) = 0.01 * sum(x)
    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    n = x.shape[0]

    def modified_rosenbrock(x):
        return np.sum(100.0 * (x[1:] - x[:-1]**2)**2 + (1 - x[:-1])**2) / 100

    def skew_term(x):
        return 0.1 * (x[0]**3 + x[1]**2 - x[2])  / (1 + x[0]**2 + x[1]**2 + x[2]**2)

    def linear_interaction(x):
        return 0.01 * np.sum(x)


    return modified_rosenbrock(x) + skew_term(x) + linear_interaction(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rosenbrock-like term with a polynomial component to introduce skewness and adjust ELA features.

    This function aims to better match the target ELA features, especially skewness and quadraticity, compared to the previous attempt.
    The Rosenbrock-like term introduces some ruggedness and the polynomial adds skew.

    Formula:
    f(x) = rosenbrock_mod(x) + poly_term(x)

    Where:
        - rosenbrock_mod(x) = sum([100.0 * (x[i+1] - x[i]**2)**2 + (1 - x[i])**2 for i in range(len(x)-1)])+ x[0]**2
        - poly_term(x) =  0.2 * (x[0]**3 - 2 * x[1]**2 + x[2])

    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rosenbrock_mod(x):
        return sum([100.0 * (x[i+1] - x[i]**2)**2 + (1 - x[i])**2 for i in range(len(x)-1)])+ x[0]**2

    def poly_term(x):
        return 0.2 * (x[0]**3 - 2 * x[1]**2 + x[2])

    return rosenbrock_mod(x) + poly_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rastrigin-like term with a polynomial component to introduce skewness.

    This function attempts to improve the skewness, fitness_std, sd_ratio and correlation compared to the prior attempt while maintaining some modality provided by the Rastrigin function.

    Formula:
    f(x) = rastrigin_mod(x) + poly_term(x)

    Where:
        - rastrigin_mod(x) = 3*3 + sum([(0.1 * xi**2 - 5 * np.cos(2 * np.pi * xi)) for xi in x])
        - poly_term(x) =  0.2 * (x[0]**3 + x[1]**2 - x[2] + 2)

    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rastrigin_mod(x):
        return 3*3 + sum([(0.1 * xi**2 - 5 * np.cos(2 * np.pi * xi)) for xi in x])

    def poly_term(x):
        return 0.2 * (x[0]**3 + x[1]**2 - x[2] + 2)

    return rastrigin_mod(x) + poly_term(x)

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rastrigin-like term with a polynomial component to introduce skewness.

    This function attempts to improve the skewness and fitness_std and lower quadratic R^2 while maintaining some modality from the Rastrigin.

    Formula:
    f(x) = rastrigin_mod(x) + poly_term(x) + offset

    Where:
        - rastrigin_mod(x) = 10*3 + sum([(0.1*xi**2 - 5 * np.cos(2 * np.pi * xi)) for xi in x])
        - poly_term(x) =  0.01 * (x[0]**3 + x[1]**2 - x[2])
        - offset = 20
    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rastrigin_mod(x):
        return 10*3 + sum([(0.1*xi**2 - 5 * np.cos(2 * np.pi * xi)) for xi in x])

    def poly_term(x):
        return 0.01 * (x[0]**3 + x[1]**2 - x[2])

    offset = 20

    return rastrigin_mod(x) + poly_term(x) + offset

import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 3D benchmark function combining a modified Rastrigin-like term with a polynomial component to introduce skewness.

    This function aims to match target ELA features, especially skewness and quadratic adj_r2 values.

    Formula:
    f(x) = rastrigin_mod(x) + poly_term(x)

    Where:
        - rastrigin_mod(x) = 10*3 + sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])
        - poly_term(x) =  0.01 * (x[0]**3 - x[1]**2 + x[2]) + 0.05 * (x[0] + x[1] - x[2])

    """
    if x.shape != (3,):
        raise ValueError("Input must be a 3D array.")

    def rastrigin_mod(x):
        return 10*3 + sum([(xi**2 - 10 * np.cos(2 * np.pi * xi)) for xi in x])

    def poly_term(x):
        return 0.01 * (x[0]**3 - x[1]**2 + x[2]) + 0.05 * (x[0] + x[1] - x[2])

    return rastrigin_mod(x) + poly_term(x)
